def transform(grid):
    h, w = len(grid), len(grid[0])

    # Split the two patterned panels at the solid divider.
    divider_row = next(
        (r for r, row in enumerate(grid) if len(set(row)) == 1), None
    )
    divider_col = next(
        (c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1),
        None
    )

    if divider_row is not None:
        first = grid[:divider_row]
        second = grid[divider_row + 1:]
    elif divider_col is not None:
        first = [row[:divider_col] for row in grid]
        second = [row[divider_col + 1:] for row in grid]
    else:
        first, second = grid, []

    def foreground(panel):
        counts = {}
        for row in panel:
            for value in row:
                counts[value] = counts.get(value, 0) + 1
        background = max(counts, key=counts.get)
        return background

    bg1 = foreground(first)
    bg2 = foreground(second) if second else None

    out = []
    for r, row in enumerate(first):
        out_row = []
        for c, value in enumerate(row):
            is_mark = value != bg1
            masked = (
                second
                and r < len(second)
                and c < len(second[r])
                and second[r][c] != bg2
            )
            out_row.append(3 if is_mark and not masked else 2)
        out.append(out_row)
    return out
